@app.cell(hide_code=True)
def _(CFG, Path, json, mo, os, re, signal, subprocess, time, urllib):
    class Sys:
        """Process, HTTP and log helpers shared by the server cells and the chat."""

        ERROR_LINE = re.compile(r"\b\w*(Error|Exception)\b:|\bERROR\b|out of memory|CUDA error|error:")
        # vLLM's own wrapper messages only say "see root cause above".
        WRAPPERS = ("Engine core initialization failed", "Frontend process failed", "EngineCore failed to start")

        @staticmethod
        def run_live(cmd, title, log=None, env=None):
            """Run a shell command, streaming its last lines to `log(title, text, done)`. Returns the exit code."""
            log = log or Sys.cell_log
            proc = subprocess.Popen(cmd, shell=True, executable="/bin/bash", stdin=subprocess.DEVNULL,
                                    stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
                                    start_new_session=True, env=env)
            lines, last = [], 0.0
            try:
                for line in proc.stdout:
                    lines.append(line.rstrip("\n"))
                    if time.time() - last > 0.5:
                        log(title, "\n".join(lines[-30:]), None)
                        last = time.time()
                code = proc.wait()
            finally:
                # An interrupted cell must not leave the command running in the background.
                if proc.poll() is None:
                    os.killpg(proc.pid, signal.SIGTERM)
            log(title, "\n".join(lines[-30:]), code)
            return code

        @staticmethod
        def cell_log(title, text, code):
            status = "jalan..." if code is None else ("selesai" if code == 0 else f"GAGAL (exit {code})")
            mo.output.replace(mo.vstack([mo.md(f"**{title}**: {status}"), mo.plain_text(text)]))

        @staticmethod
        def http(method, url, body=None, headers=None, timeout=10):
            """Return (status, text). status is None when the request never got an answer."""
            data = json.dumps(body).encode() if isinstance(body, (dict, list)) else body
            hdr = {"User-Agent": CFG.USER_AGENT, **(headers or {})}
            if data is not None and "Content-Type" not in hdr:
                hdr["Content-Type"] = "application/json"
            try:
                req = urllib.request.Request(url, data=data, method=method, headers=hdr)
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    return resp.status, resp.read().decode("utf-8", "replace")
            except urllib.error.HTTPError as e:
                return e.code, e.read().decode("utf-8", "replace")
            except Exception as e:
                return None, f"{type(e).__name__}: {e}"

        @staticmethod
        def get_json(url, headers=None, timeout=10):
            status, text = Sys.http("GET", url, headers=headers, timeout=timeout)
            if status != 200:
                raise RuntimeError(f"GET {url} -> {status}: {text[:300]}")
            return json.loads(text)

        @staticmethod
        def tail(path, n=30, max_bytes=65536):
            try:
                with open(path, "rb") as f:
                    f.seek(0, os.SEEK_END)
                    f.seek(max(0, f.tell() - max_bytes))
                    return "\n".join(f.read().decode("utf-8", "replace").splitlines()[-n:])
            except FileNotFoundError:
                return "(belum ada log)"

        @staticmethod
        def log_errors(path, n=12):
            """Last distinct error lines of a log, without vLLM's generic wrapper messages."""
            found = []
            for line in Sys.tail(path, 5000, max_bytes=1 << 20).splitlines():
                if Sys.ERROR_LINE.search(line) and not any(w in line for w in Sys.WRAPPERS) and line not in found:
                    found.append(line)
            return "\n".join(found[-n:])

        @staticmethod
        def pid_alive(pid_file):
            try:
                pid = int(Path(pid_file).read_text())
                os.killpg(pid, 0)
                return pid
            except (FileNotFoundError, ValueError, ProcessLookupError, PermissionError):
                return None

        @staticmethod
        def kill_group(pid_file, wait=60):
            """SIGTERM the process group in pid_file, SIGKILL after `wait` seconds. Returns the pid or None."""
            try:
                pid = int(Path(pid_file).read_text())
            except (FileNotFoundError, ValueError):
                return None
            for sig, limit in ((signal.SIGTERM, wait), (signal.SIGKILL, 10)):
                try:
                    os.killpg(pid, sig)
                except ProcessLookupError:
                    break
                for _ in range(limit):
                    try:
                        os.waitpid(-pid, os.WNOHANG)
                    except ChildProcessError:
                        pass
                    try:
                        os.killpg(pid, 0)
                    except ProcessLookupError:
                        break
                    time.sleep(1)
                else:
                    continue
                break
            Path(pid_file).unlink(missing_ok=True)
            return pid

        @staticmethod
        def gpu_line():
            r = subprocess.run("nvidia-smi --query-gpu=utilization.gpu,memory.used,memory.total --format=csv,noheader,nounits",
                               shell=True, capture_output=True, text=True)
            try:
                util, used, total = [float(x) for x in r.stdout.strip().split("\n")[0].split(",")]
                return {"util": util, "used_gb": used / 1024, "total_gb": total / 1024}
            except ValueError:
                return None

        @staticmethod
        def metrics(url):
            status, body = Sys.http("GET", url, timeout=2)
            out = {}
            if status == 200:
                for line in body.splitlines():
                    if line.startswith("#") or " " not in line:
                        continue
                    try:
                        name = line.split("{")[0].split(" ")[0]
                        out[name] = out.get(name, 0.0) + float(line.rsplit(" ", 1)[1])
                    except ValueError:
                        pass
            return out

    return (Sys,)


@app.cell(hide_code=True)
def _(
    CFG,
    EMBEDDER,
    PRESETS,
    Path,
    Sys,
    hashlib,
    json,
    os,
    re,
    subprocess,
    sys,
    thinking_kwargs,
    threading,
    time,
    urllib,
):
    import http.server as _hs


    def _make_proxy(upstream, ctx_len):
        """HTTP handler that forwards to llama-server and adds what the chat expects from vLLM:
        max_model_len in /v1/models and /tokenize with chat messages."""

        class Proxy(_hs.BaseHTTPRequestHandler):
            protocol_version = "HTTP/1.1"

            def log_message(self, *a):
                pass

            def _call(self, method, path, body=None):
                hdr = {k: v for k, v in self.headers.items() if k.lower() in ("authorization", "content-type", "accept")}
                return urllib.request.urlopen(urllib.request.Request(upstream + path, data=body, method=method, headers=hdr),
                                              timeout=7200)

            def _json(self, code, obj):
                data = json.dumps(obj).encode()
                self.send_response(code)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(data)))
                self.end_headers()
                self.wfile.write(data)

            def _handle(self, method):
                body = self.rfile.read(int(self.headers.get("Content-Length") or 0)) if method == "POST" else None
                try:
                    if method == "GET" and self.path.startswith("/v1/models"):
                        d = json.loads(self._call("GET", self.path).read())
                        for m in d.get("data", []):
                            m["max_model_len"] = ctx_len
                        return self._json(200, d)
                    if method == "POST" and self.path == "/tokenize" and b'"messages"' in (body or b""):
                        req = json.loads(body)
                        req.pop("model", None)
                        prompt = json.loads(self._call("POST", "/apply-template", json.dumps(req).encode()).read())["prompt"]
                        toks = json.loads(self._call("POST", "/tokenize", json.dumps({"content": prompt}).encode()).read())["tokens"]
                        return self._json(200, {"count": len(toks)})
                    resp = self._call(method, self.path, body)
                    self.send_response(resp.status)
                    self.send_header("Content-Type", resp.headers.get("Content-Type", "application/json"))
                    self.send_header("Transfer-Encoding", "chunked")
                    self.end_headers()
                    while True:
                        chunk = resp.read1(65536)
                        if not chunk:
                            break
                        self.wfile.write(b"%x\r\n%s\r\n" % (len(chunk), chunk))
                        self.wfile.flush()
                    self.wfile.write(b"0\r\n\r\n")
                except urllib.error.HTTPError as e:
                    self._json(e.code, {"error": e.read().decode("utf-8", "replace")[:2000]})
                except (BrokenPipeError, ConnectionResetError):
                    pass
                except Exception as e:
                    self._json(503, {"error": f"{type(e).__name__}: {e}"})

            def do_GET(self):
                self._handle("GET")

            def do_POST(self):
                self._handle("POST")

        return Proxy


    class ServerManager:
        """Install, start and stop the model server (vLLM or llama.cpp) and the embedder.
        Used by the control cells and by the chat's model switcher."""

        def __init__(self):
            self.lock = threading.RLock()
            self.pid = {k: CFG.WORK / f"{k}.pid" for k in ("vllm", "llama", "embed")}
            self.logf = {k: CFG.LOG_DIR / f"{k}.log" for k in ("vllm", "llama", "embed")}
            self.state_file = CFG.WORK / "server.json"
            self.proxy = None
            self.procs = {}
            self.state = {"phase": "idle", "preset": None, "ctx": None, "mtp": False, "embed": False,
                          "warnings": [], "error": "", "started": None}
            try:
                saved = json.loads(self.state_file.read_text())
                if saved.get("preset") and any(Sys.pid_alive(self.pid[k]) for k in ("vllm", "llama")):
                    self.state.update(saved)
                    if saved.get("backend") == "llama" and Sys.pid_alive(self.pid["llama"]):
                        self._start_proxy(saved["ctx"])
            except (FileNotFoundError, ValueError):
                pass

        # ---------- info ----------

        def preset(self):
            return PRESETS.get(self.state.get("preset") or "")

        def current(self):
            """What the chat needs: URLs, the preset, the context length."""
            root = CFG.BASE_URL.rstrip("/").removesuffix("/v1") if CFG.BASE_URL else f"http://127.0.0.1:{CFG.PORT}"
            return {"root_url": root, "base_url": root + "/v1", "health_url": root + "/health",
                    "preset_name": self.state.get("preset"), "preset": self.preset(), "ctx": self.state.get("ctx"),
                    "phase": self.state.get("phase"), "warnings": list(self.state.get("warnings") or [])}

        def ready(self):
            cur = self.current()
            if CFG.BASE_URL:
                return Sys.http("GET", cur["health_url"], timeout=2)[0] == 200
            return self.state.get("phase") == "ready" and Sys.http("GET", cur["health_url"], timeout=2)[0] == 200

        def status(self):
            backend = (self.preset() or {}).get("backend")
            log = self.logf.get(backend) if backend else None
            return {**self.state, "backend": backend,
                    "log": Sys.tail(log, 40) if log else "", "errors": Sys.log_errors(log) if log else "",
                    "embed_ready": self.embed_ready()}

        def _save(self):
            self.state["backend"] = (self.preset() or {}).get("backend")
            self.state_file.write_text(json.dumps(self.state))

        # ---------- install ----------

        def install(self, log=None):
            """Compiler bits, browser tools, vLLM (own venv), llama.cpp (pinned release). Safe to run again."""
            log = log or Sys.cell_log
            gpu = subprocess.run("nvidia-smi --query-gpu=driver_version --format=csv,noheader", shell=True,
                                 capture_output=True, text=True).stdout.strip()
            try:
                driver = int(gpu.split(".")[0])
            except ValueError:
                driver = 0
            if not driver:
                raise RuntimeError("GPU belum terdeteksi. Nyalakan GPU lewat notebook specs, lalu Install lagi.")
            # Triton needs cc, FlashInfer JIT needs ninja and links -lcudart from nvidia/cu13/lib64,
            # where the pip CUDA runtime only ships libcudart.so.13.
            Sys.run_live(
                "(command -v cc && command -v ninja) >/dev/null && echo 'cc + ninja ada' "
                "|| (apt-get -qq update && apt-get -qq install -y gcc g++ ninja-build >/dev/null && echo 'gcc + ninja terpasang') "
                "|| echo 'gcc/ninja gagal dipasang'; "
                "for D in /usr/local/lib/python3.*/site-packages/nvidia/cu13 "
                f"{CFG.VENV}/lib/python3.*/site-packages/nvidia/cu13; do "
                "[ -d \"$D\" ] || continue; L=$(find \"$D\" -name 'libcudart.so.1*' | head -1); "
                "[ -n \"$L\" ] && mkdir -p \"$D/lib64\" && ln -sf \"$L\" \"$D/lib64/libcudart.so\" && echo \"libcudart.so -> $L\"; done",
                "Persiapan compiler", log)
            pins = " ".join(f"'{k}=={v}'" for k, v in CFG.PIP_PINS.items())
            code = Sys.run_live(
                f"(uv pip install --python {sys.executable} {pins} || {sys.executable} -m pip install -q {pins}) "
                f"&& {sys.executable} -m playwright install --with-deps chromium firefox "
                f"&& {sys.executable} -m camoufox fetch",
                "Paket kernel + Camoufox + Playwright", log)
            if code != 0:
                raise RuntimeError("Gagal memasang paket kernel. Lihat log di atas.")
            if not CFG.VLLM_OK.exists():
                pkg = (f'"https://github.com/vllm-project/vllm/releases/download/v{CFG.VLLM_VERSION}/'
                       f'vllm-{CFG.VLLM_VERSION}+cu129-cp38-abi3-manylinux_2_28_x86_64.whl" --torch-backend=cu129'
                       if driver < 580 else f"vllm=={CFG.VLLM_VERSION} --torch-backend=cu130")
                code = Sys.run_live(
                    f"set -e; uv venv --allow-existing {CFG.VENV}; uv pip install --python {CFG.VENV}/bin/python {pkg}; "
                    f"{CFG.VLLM_BIN} download-kernels || echo 'download-kernels dilewati'",
                    f"vLLM {CFG.VLLM_VERSION}", log)
                if code != 0:
                    raise RuntimeError("Gagal memasang vLLM. Lihat log di atas.")
                CFG.VLLM_OK.touch()
            if not self.llama_bin():
                rel = Sys.get_json(f"https://api.github.com/repos/ggml-org/llama.cpp/releases/tags/{CFG.LLAMA_TAG}", timeout=30)
                urls = [a["browser_download_url"] for a in rel["assets"]
                        if CFG.LLAMA_ASSET in a["name"] and a["name"].endswith("-x64.tar.gz")]
                code = Sys.run_live(
                    f"set -e; rm -rf {CFG.LLAMA_DIR}; mkdir -p {CFG.LLAMA_DIR}; cd {CFG.LLAMA_DIR}; "
                    + "; ".join(f"curl -fsSL '{u}' | tar xz" for u in urls) + "; find . -name llama-server -type f",
                    f"llama.cpp {CFG.LLAMA_TAG}", log)
                if code != 0 or not self.llama_bin():
                    raise RuntimeError("Gagal memasang llama.cpp. Lihat log di atas.")
            return True

        def installed(self):
            return CFG.VLLM_OK.exists() and bool(self.llama_bin())

        def llama_bin(self):
            return next(iter(CFG.LLAMA_DIR.rglob("llama-server")), None) if CFG.LLAMA_DIR.exists() else None

        def _llama_env(self):
            libs = sorted({str(p.parent) for p in CFG.LLAMA_DIR.rglob("*.so*")})
            return {**os.environ, "LD_LIBRARY_PATH": ":".join(libs + [os.environ.get("LD_LIBRARY_PATH", "")])}

        # ---------- download ----------

        def fetch(self, repo, revision, filename=None, log=None):
            """Download a file (or a whole repo) at a pinned revision into MODEL_DIR. Returns the local path."""
            dest = CFG.MODEL_DIR / repo.replace("/", "__") / revision[:12]
            target = dest / filename if filename else dest
            marker = dest / f".ok-{hashlib.sha1((filename or '*').encode()).hexdigest()[:8]}"
            if marker.exists():
                return target
            call = (f"hf_hub_download('{repo}', '{filename}', revision='{revision}', local_dir='{dest}')" if filename
                    else f"snapshot_download('{repo}', revision='{revision}', local_dir='{dest}')")
            code = Sys.run_live(
                f"{sys.executable} -c \"from huggingface_hub import hf_hub_download, snapshot_download; {call}; print('selesai')\"",
                f"Download {repo}{'/' + filename if filename else ''}", log)
            if code != 0:
                raise RuntimeError(f"Download {repo} gagal. Lihat log di atas.")
            marker.touch()
            return target

        # ---------- start / stop ----------

        def start(self, name, ctx, mtp=True, embed=False, log=None):
            """Download (if needed) and launch a preset. Returns once the process is running;
            a watcher thread marks it ready, or retries without MTP if the drafter makes it crash."""
            p = PRESETS[name]
            if ctx > p["yarn_max"]:
                raise ValueError(f"{name} maksimal {p['yarn_max']:,} token. Pilih konteks yang lebih kecil.")
            if not self.installed() and not CFG.BASE_URL:
                raise RuntimeError("Belum terpasang. Klik Install dulu.")
            with self.lock:
                self.stop(keep_embed=embed)
                self.state.update(phase="downloading", preset=name, ctx=ctx, mtp=bool(mtp and p.get("mtp")),
                                  embed=embed, warnings=[], error="", started=time.time())
                self._save()
            try:
                if p["backend"] == "vllm":
                    files = {"model": self.fetch(p["repo"], p["revision"], log=log)}
                    if self.state["mtp"] and p.get("mtp") == "draft":
                        files["draft"] = self.fetch(*p["draft_hf"], log=log)
                else:
                    files = {"model": self.fetch(p["repo"], p["revision"], p["file"], log=log)}
                    if p.get("mmproj"):
                        files["mmproj"] = self.fetch(p["mmproj"][0], p["mmproj"][2], p["mmproj"][1], log=log)
                    if self.state["mtp"] and p.get("mtp") == "draft":
                        files["draft"] = self.fetch(p["draft_gguf"][0], p["draft_gguf"][2], p["draft_gguf"][1], log=log)
                if embed:
                    self.embed_start(log=log)
            except Exception as e:
                self.state.update(phase="failed", error=str(e))
                self._save()
                raise
            with self.lock:
                self._launch(p, files, ctx, self.state["mtp"])
            threading.Thread(target=self._watch, args=(p, files, ctx), daemon=True).start()
            return self.state

        def _vllm_cmd(self, p, files, ctx, mtp):
            yarn = ctx > p["max_ctx"]
            top = p["thinking"][-1]
            cmd = [str(CFG.VLLM_BIN), "serve", str(files["model"]), "--served-model-name", CFG.SERVED_NAME,
                   "--host", "127.0.0.1", "--port", str(CFG.PORT), "--api-key", CFG.API_KEY,
                   "--max-model-len", str(ctx),
                   # One long conversation: all the memory, no batch sharing.
                   "--gpu-memory-utilization", "0.92" if self.state.get("embed") else "0.94",
                   "--max-num-seqs", "1",
                   # Every turn resends the whole history; prefix caching reuses its KV instead of recomputing it.
                   "--enable-prefix-caching", "--max-num-batched-tokens", "8192",
                   "--reasoning-parser", p["reasoning_parser"], "--enable-auto-tool-choice",
                   "--tool-call-parser", p["tool_parser"],
                   "--default-chat-template-kwargs", json.dumps(thinking_kwargs(p, top)),
                   # BF16 KV scored best at native context; with YaRN, FP8 KV scored the same (MRCR v2, n=15).
                   "--kv-cache-dtype", p.get("kv_dtype") or ("fp8" if yarn else "auto")]
            if p.get("quantization"):
                cmd += ["--quantization", p["quantization"]]
            cmd += list(p.get("vllm_args") or [])
            if yarn and p["family"] == "qwen":
                # YaRN override from the Qwen3.8 model card: factor 4.0 for 1M, 2.0 for ~524K.
                rope = {"mrope_interleaved": True, "mrope_section": [11, 11, 10], "rope_type": "yarn",
                        "rope_theta": 10000000, "partial_rotary_factor": 0.25,
                        "factor": 4.0 if ctx > 524288 else 2.0, "original_max_position_embeddings": 262144}
                cmd += ["--hf-overrides", json.dumps({"text_config": {"rope_parameters": rope}})]
            if mtp and p.get("mtp") == "heads":
                cmd += ["--speculative-config", json.dumps({"method": "mtp", "num_speculative_tokens": 3})]
            elif mtp and p.get("mtp") == "draft" and files.get("draft"):
                # gemma4_assistant drafter: vLLM maps it to gemma4_mtp, it reads the target's KV cache.
                cmd += ["--speculative-config", json.dumps({"model": str(files["draft"]), "num_speculative_tokens": 3})]
            return cmd

        def _llama_cmd(self, p, files, ctx, mtp):
            cmd = [str(self.llama_bin()), "-m", str(files["model"]), "--alias", CFG.SERVED_NAME,
                   "--host", "127.0.0.1", "--port", str(CFG.LLAMA_PORT), "--api-key", CFG.API_KEY,
                   "-c", str(ctx), "-ngl", "999", "-np", "1", "-fa", "on", "--jinja", "--reasoning-format", "deepseek",
                   "-ctk", "q8_0", "-ctv", "q8_0", "--metrics"]
            if files.get("mmproj"):
                cmd += ["--mmproj", str(files["mmproj"])]
            if ctx > p["max_ctx"]:
                cmd += ["--rope-scaling", "yarn", "--rope-scale", "4" if ctx > 524288 else "2", "--yarn-orig-ctx", "262144"]
            if mtp and p.get("mtp") == "heads":
                cmd += ["--spec-type", "draft-mtp", "--spec-draft-n-max", "2", "-ctkd", "q8_0", "-ctvd", "q8_0"]
            elif mtp and p.get("mtp") == "draft" and files.get("draft"):
                cmd += ["--spec-type", "draft-mtp", "-md", str(files["draft"]), "-ngld", "all",
                        "--spec-draft-n-max", "3", "-ctkd", "q8_0", "-ctvd", "q8_0"]
            return cmd

        def _launch(self, p, files, ctx, mtp):
            backend = p["backend"]
            if backend == "vllm":
                cmd = self._vllm_cmd(p, files, ctx, mtp)
                env = {**os.environ, "VLLM_ALLOW_LONG_MAX_MODEL_LEN": "1", "PYTORCH_CUDA_ALLOC_CONF": "expandable_segments:True",
                       # FlashInfer JIT looks for ninja and nvcc on PATH; molab does not export the CUDA bin dir.
                       "PATH": f"{CFG.VLLM_BIN.parent}:/usr/local/cuda/bin:{os.environ.get('PATH', '')}",
                       "CUDA_HOME": os.environ.get("CUDA_HOME", "/usr/local/cuda")}
            else:
                cmd = self._llama_cmd(p, files, ctx, mtp)
                env = self._llama_env()
            (CFG.LOG_DIR / f"{backend}.cmd").write_text(" ".join(cmd))
            proc = subprocess.Popen(cmd, stdin=subprocess.DEVNULL, stdout=open(self.logf[backend], "w"),
                                    stderr=subprocess.STDOUT, start_new_session=True, env=env)
            self.pid[backend].write_text(str(proc.pid))
            self.procs[backend] = proc
            if backend == "llama":
                self._start_proxy(ctx)
            self.state.update(phase="loading", mtp=mtp)
            self._save()

        def _start_proxy(self, ctx):
            if self.proxy:
                self.proxy.shutdown()
                self.proxy.server_close()
            self.proxy = _hs.ThreadingHTTPServer(("127.0.0.1", CFG.PORT), _make_proxy(f"http://127.0.0.1:{CFG.LLAMA_PORT}", ctx))
            threading.Thread(target=self.proxy.serve_forever, daemon=True).start()

        SPEC_ERROR = re.compile(r"specul|draft[_ ]?model|drafter|\bmtp\b|eagle|gemma4_mtp|spec-type|spec_draft", re.I)

        @staticmethod
        def jit_logs(log_tail):
            """vLLM's JIT kernels (humming / NVRTC) write their compiler output to a folder named in the error.
            Show it, otherwise the real cause stays hidden."""
            out = []
            for path in dict.fromkeys(re.findall(r"compiler logs: (\S+)", log_tail)):
                p = Path(path)
                files = sorted(p.glob("*")) if p.is_dir() else [p] if p.exists() else []
                for f in files:
                    if f.suffix in (".log", ".txt", ".err") or "log" in f.name.lower():
                        out.append(f"--- {f} ---\n" + f.read_text(errors="replace")[-4000:])
                if not out and files:
                    out.append(f"--- isi {p} ---\n" + "\n".join(f.name for f in files))
            return ("\n\n" + "\n\n".join(out)) if out else ""

        @staticmethod
        def hint(log_tail, p):
            if "NVRTCCompiler failed" in log_tail or "humming" in log_tail:
                return ("\n\nPenyebab: kernel Humming vLLM meng-compile kernel saat jalan (NVRTC) dan gagal di GPU/driver ini. "
                        "Paksa kernel lain lewat preset: vllm_args=['--kernel-config', "
                        "'{\"linear_backend_per_quant\":{\"<kunci kuantisasi>\":\"marlin\"}}'] (kunci: w8a16_fp8, mixed_precision, "
                        "mxfp4, nvfp4_w4a16, ...). Log compiler ada di atas.")
            if "out of memory" in log_tail.lower():
                return "\n\nSaran: VRAM tidak cukup. Kecilkan konteks atau matikan embedder."
            return ""

        def _watch(self, p, files, ctx):
            backend = p["backend"]
            health = (f"http://127.0.0.1:{CFG.PORT}/health" if backend == "vllm"
                      else f"http://127.0.0.1:{CFG.LLAMA_PORT}/health")
            while self.state.get("preset") and PRESETS.get(self.state["preset"]) is p:
                proc = self.procs.get(backend)
                if proc is not None and proc.poll() is not None:
                    log_tail = Sys.tail(self.logf[backend], 400)
                    # MTP is required: no silent restart without it. Show the real cause instead.
                    error = Sys.log_errors(self.logf[backend]) or "server berhenti"
                    if self.state.get("mtp") and self.SPEC_ERROR.search(log_tail):
                        error = "Gagal di bagian MTP/drafter (MTP wajib, server tidak dijalankan ulang tanpa MTP).\n" + error
                    self.state.update(phase="failed", error=error + self.jit_logs(log_tail) + self.hint(log_tail, p))
                    self._save()
                    return
                if Sys.http("GET", health, timeout=2)[0] == 200:
                    self.state.update(phase="ready")
                    self._save()
                    return
                time.sleep(3)

        def stop(self, keep_embed=False):
            with self.lock:
                if self.proxy:
                    self.proxy.shutdown()
                    self.proxy.server_close()
                    self.proxy = None
                stopped = [k for k in ("vllm", "llama") if Sys.kill_group(self.pid[k])]
                for k in stopped:
                    self.procs.pop(k, None)
                if not keep_embed:
                    self.embed_stop()
                self.state.update(phase="idle", preset=None, ctx=None, warnings=[], error="")
                self._save()
                return stopped

        # ---------- embedder ----------

        def embed_start(self, log=None):
            if self.embed_ready() or Sys.pid_alive(self.pid["embed"]):
                return
            path = self.fetch(EMBEDDER["repo"], EMBEDDER["revision"], EMBEDDER["file"], log=log)
            cmd = [str(self.llama_bin()), "-m", str(path), "--embedding", "--pooling", "last", "--host", "127.0.0.1",
                   "--port", str(CFG.EMBED_PORT), "--api-key", CFG.API_KEY, "-ngl", "999", "-c", "8192", "-ub", "8192",
                   "-np", "1"]
            proc = subprocess.Popen(cmd, stdin=subprocess.DEVNULL, stdout=open(self.logf["embed"], "w"),
                                    stderr=subprocess.STDOUT, start_new_session=True, env=self._llama_env())
            self.pid["embed"].write_text(str(proc.pid))
            self.procs["embed"] = proc
            self.state["embed"] = True

        def embed_stop(self):
            Sys.kill_group(self.pid["embed"])
            self.procs.pop("embed", None)
            self.state["embed"] = False

        def embed_url(self):
            return os.environ.get("QCHAT_EMBED_URL") or f"http://127.0.0.1:{CFG.EMBED_PORT}"

        def embed_ready(self):
            return Sys.http("GET", self.embed_url() + "/health", timeout=1)[0] == 200


    SERVERS = ServerManager()
    return (SERVERS,)


@app.cell(hide_code=True)
def _(CTX_CHOICES, PRESETS, STORE, mo):
    # Last used server settings are stored in the database, so a restored backup starts with them selected.
    _last = STORE.meta_get("server", {}) or {}
    _ctx_label = next((k for k, v in CTX_CHOICES.items() if v == _last.get("ctx")), "512K (YaRN)")
    ctl_preset = mo.ui.dropdown(options=list(PRESETS), value=_last.get("preset") if _last.get("preset") in PRESETS else next(iter(PRESETS)),
                                label="Model", full_width=True)
    ctl_ctx = mo.ui.dropdown(options=CTX_CHOICES, value=_ctx_label, label="Konteks")
    ctl_mtp = mo.ui.switch(value=_last.get("mtp", True), label="MTP (lebih cepat)")
    ctl_embed = mo.ui.switch(value=_last.get("embed", True), label="Embedder (pencarian memory lebih pintar)")
    ctl_install = mo.ui.run_button(label="Install")
    ctl_start = mo.ui.run_button(label="Start", kind="success")
    ctl_stop = mo.ui.run_button(label="Stop", kind="danger")
    mo.vstack([
        mo.md("### Server model"),
        ctl_preset,
        mo.hstack([ctl_ctx, ctl_mtp, ctl_embed], justify="start", align="center", gap=2),
        mo.hstack([ctl_install, ctl_start, ctl_stop], justify="start"),
    ])
    return (
        ctl_ctx,
        ctl_embed,
        ctl_install,
        ctl_mtp,
        ctl_preset,
        ctl_start,
        ctl_stop,
    )


@app.cell(hide_code=True)
def _(
    PRESETS,
    SERVERS,
    STORE,
    ctl_ctx,
    ctl_embed,
    ctl_install,
    ctl_mtp,
    ctl_preset,
    ctl_start,
    ctl_stop,
    mo,
):
    def _act():
        if ctl_install.value:
            try:
                SERVERS.install()
                return mo.callout(mo.md("Install selesai. Pilih model lalu klik **Start**."), kind="success")
            except Exception as e:
                return mo.callout(mo.md(f"Install gagal: {e}"), kind="danger")
        if ctl_start.value:
            p = PRESETS[ctl_preset.value]
            if ctl_ctx.value > p["yarn_max"]:
                return mo.callout(mo.md(f"**{ctl_preset.value}** maksimal {p['yarn_max']:,} token. Pilih konteks yang lebih kecil."),
                                  kind="danger")
            try:
                SERVERS.start(ctl_preset.value, ctl_ctx.value, mtp=ctl_mtp.value, embed=ctl_embed.value)
            except Exception as e:
                return mo.callout(mo.md(f"Start gagal: {e}"), kind="danger")
            STORE.meta_set("server", {"preset": ctl_preset.value, "ctx": ctl_ctx.value, "mtp": ctl_mtp.value,
                                      "embed": ctl_embed.value})
            note = ""
            if ctl_ctx.value > p["max_ctx"] and p.get("yarn_exp"):
                note = ("\n\n**YaRN eksperimental:** model ini tidak punya resep YaRN resmi. Cek `n_ctx` di log dan uji "
                        "ingatan sebelum percaya jawaban di atas 262K.")
            return mo.callout(mo.md(f"**{ctl_preset.value}** dimulai dengan konteks {ctl_ctx.value:,}. "
                                    f"Pantau status di bawah.{note}"), kind="neutral")
        if ctl_stop.value:
            stopped = SERVERS.stop()
            return mo.md("Server dihentikan." if stopped else "Tidak ada server yang jalan.")
        return None


    _act()


@app.cell(hide_code=True)
def _(SERVERS, Sys, mo, time):
    def _status_view():
        st = SERVERS.status()
        phase = st["phase"]
        kinds = {"ready": "success", "failed": "danger"}
        titles = {"idle": "Belum di-start.", "downloading": "Download model…", "loading": "Memuat model…",
                  "ready": "READY: chat siap dipakai.", "failed": "Server gagal."}
        head = f"**{titles.get(phase, phase)}**"
        if st.get("preset"):
            head += f" {st['preset']} · konteks {st['ctx']:,} · MTP {'nyala' if st.get('mtp') else 'mati'}"
        if st.get("embed"):
            head += f" · embedder {'siap' if st.get('embed_ready') else 'memuat'}"
        parts = [mo.callout(mo.md(head), kind=kinds.get(phase, "neutral"))]
        for w in st.get("warnings") or []:
            parts.append(mo.callout(mo.md(w), kind="warn"))
        if st.get("error"):
            parts.append(mo.callout(mo.plain_text(st["error"]), kind="danger"))
        gpu = Sys.gpu_line()
        if gpu:
            parts.append(mo.md(f"`GPU {gpu['util']:.0f}% · VRAM {gpu['used_gb']:.1f} / {gpu['total_gb']:.0f} GB`"))
        if st.get("log"):
            parts.append(mo.accordion({"Log server (40 baris terakhir)": mo.plain_text(st["log"])}))
        return mo.vstack(parts)


    def _watch_status():
        me = mo.current_thread()
        while not me.should_exit:
            mo.output.replace(_status_view())
            time.sleep(3)


    if mo.running_in_notebook():
        mo.Thread(target=_watch_status, daemon=True).start()
    else:
        _status_view()


@app.cell(hide_code=True)
def _(CFG, Path, json, sqlite3, threading, time):
    _SCHEMA_V1 = """
    CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT);
    CREATE TABLE IF NOT EXISTS stories (
        id INTEGER PRIMARY KEY, title TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}',
        created REAL NOT NULL, updated REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS story_cards (
        story_id INTEGER NOT NULL, card_id INTEGER NOT NULL, role TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY (story_id, card_id, role)
    );
    CREATE TABLE IF NOT EXISTS chats (
        id INTEGER PRIMARY KEY, story_id INTEGER, title TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'chat',
        system TEXT NOT NULL DEFAULT '', settings TEXT NOT NULL DEFAULT '{}', head_id INTEGER,
        strip_node INTEGER NOT NULL DEFAULT 0, epoch INTEGER NOT NULL DEFAULT 0,
        created REAL NOT NULL, updated REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS messages (
        id INTEGER PRIMARY KEY, chat_id INTEGER NOT NULL, parent_id INTEGER, role TEXT NOT NULL,
        content TEXT NOT NULL DEFAULT '', reasoning TEXT NOT NULL DEFAULT '', tool_calls TEXT, tool_call_id TEXT,
        ooc INTEGER NOT NULL DEFAULT 0, pinned INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'final',
        meta TEXT NOT NULL DEFAULT '{}', created REAL NOT NULL
    );
    CREATE INDEX IF NOT EXISTS messages_chat ON messages (chat_id, parent_id);
    CREATE VIRTUAL TABLE IF NOT EXISTS messages_fts USING fts5(content, reasoning, content='messages', content_rowid='id');
    CREATE TRIGGER IF NOT EXISTS messages_ai AFTER INSERT ON messages BEGIN
        INSERT INTO messages_fts(rowid, content, reasoning) VALUES (new.id, new.content, new.reasoning);
    END;
    CREATE TRIGGER IF NOT EXISTS messages_ad AFTER DELETE ON messages BEGIN
        INSERT INTO messages_fts(messages_fts, rowid, content, reasoning) VALUES ('delete', old.id, old.content, old.reasoning);
    END;
    CREATE TRIGGER IF NOT EXISTS messages_au AFTER UPDATE OF content, reasoning ON messages BEGIN
        INSERT INTO messages_fts(messages_fts, rowid, content, reasoning) VALUES ('delete', old.id, old.content, old.reasoning);
        INSERT INTO messages_fts(rowid, content, reasoning) VALUES (new.id, new.content, new.reasoning);
    END;
    CREATE TABLE IF NOT EXISTS attachments (
        id INTEGER PRIMARY KEY, message_id INTEGER NOT NULL, kind TEXT NOT NULL,
        mime TEXT NOT NULL, name TEXT NOT NULL, data BLOB NOT NULL
    );
    CREATE INDEX IF NOT EXISTS attachments_msg ON attachments (message_id);
    CREATE TABLE IF NOT EXISTS summaries (
        id INTEGER PRIMARY KEY, chat_id INTEGER NOT NULL, node_id INTEGER NOT NULL, from_id INTEGER NOT NULL DEFAULT 0,
        level TEXT NOT NULL DEFAULT 'chunk', text TEXT NOT NULL, core TEXT NOT NULL DEFAULT '', created REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS snapshots (
        chat_id INTEGER NOT NULL, epoch INTEGER NOT NULL, text TEXT NOT NULL, created REAL NOT NULL,
        PRIMARY KEY (chat_id, epoch)
    );
    CREATE TABLE IF NOT EXISTS pending_changes (
        id INTEGER PRIMARY KEY, story_id INTEGER, chat_id INTEGER, text TEXT NOT NULL, created REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS chapters (
        id INTEGER PRIMARY KEY, chat_id INTEGER NOT NULL, message_id INTEGER NOT NULL, title TEXT NOT NULL, created REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS card_schemas (type TEXT PRIMARY KEY, version INTEGER NOT NULL, json TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS cards (
        id INTEGER PRIMARY KEY, type TEXT NOT NULL, name TEXT NOT NULL, data TEXT NOT NULL DEFAULT '{}', avatar BLOB,
        version INTEGER NOT NULL DEFAULT 1, created REAL NOT NULL, updated REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS card_versions (
        card_id INTEGER NOT NULL, version INTEGER NOT NULL, data TEXT NOT NULL, created REAL NOT NULL,
        PRIMARY KEY (card_id, version)
    );
    CREATE TABLE IF NOT EXISTS lore_entries (
        id INTEGER PRIMARY KEY, card_id INTEGER NOT NULL, kind TEXT NOT NULL DEFAULT 'istilah', title TEXT NOT NULL,
        keys TEXT NOT NULL DEFAULT '', text TEXT NOT NULL DEFAULT '', core INTEGER NOT NULL DEFAULT 0, updated REAL NOT NULL
    );
    CREATE VIRTUAL TABLE IF NOT EXISTS lore_fts USING fts5(title, keys, text, content='lore_entries', content_rowid='id');
    CREATE TRIGGER IF NOT EXISTS lore_ai AFTER INSERT ON lore_entries BEGIN
        INSERT INTO lore_fts(rowid, title, keys, text) VALUES (new.id, new.title, new.keys, new.text);
    END;
    CREATE TRIGGER IF NOT EXISTS lore_ad AFTER DELETE ON lore_entries BEGIN
        INSERT INTO lore_fts(lore_fts, rowid, title, keys, text) VALUES ('delete', old.id, old.title, old.keys, old.text);
    END;
    CREATE TRIGGER IF NOT EXISTS lore_au AFTER UPDATE ON lore_entries BEGIN
        INSERT INTO lore_fts(lore_fts, rowid, title, keys, text) VALUES ('delete', old.id, old.title, old.keys, old.text);
        INSERT INTO lore_fts(rowid, title, keys, text) VALUES (new.id, new.title, new.keys, new.text);
    END;
    CREATE TABLE IF NOT EXISTS facts (
        id INTEGER PRIMARY KEY, world_card_id INTEGER, claim TEXT NOT NULL, source_url TEXT NOT NULL DEFAULT '',
        source_title TEXT NOT NULL DEFAULT '', checked REAL NOT NULL, confidence REAL NOT NULL DEFAULT 0.7,
        status TEXT NOT NULL DEFAULT 'terverifikasi', tags TEXT NOT NULL DEFAULT ''
    );
    CREATE VIRTUAL TABLE IF NOT EXISTS facts_fts USING fts5(claim, tags, content='facts', content_rowid='id');
    CREATE TRIGGER IF NOT EXISTS facts_ai AFTER INSERT ON facts BEGIN
        INSERT INTO facts_fts(rowid, claim, tags) VALUES (new.id, new.claim, new.tags);
    END;
    CREATE TRIGGER IF NOT EXISTS facts_ad AFTER DELETE ON facts BEGIN
        INSERT INTO facts_fts(facts_fts, rowid, claim, tags) VALUES ('delete', old.id, old.claim, old.tags);
    END;
    CREATE TRIGGER IF NOT EXISTS facts_au AFTER UPDATE ON facts BEGIN
        INSERT INTO facts_fts(facts_fts, rowid, claim, tags) VALUES ('delete', old.id, old.claim, old.tags);
        INSERT INTO facts_fts(rowid, claim, tags) VALUES (new.id, new.claim, new.tags);
    END;
    CREATE TABLE IF NOT EXISTS timeline (
        id INTEGER PRIMARY KEY, card_id INTEGER NOT NULL, at TEXT NOT NULL, title TEXT NOT NULL, text TEXT NOT NULL DEFAULT ''
    );
    CREATE TABLE IF NOT EXISTS status_events (
        id INTEGER PRIMARY KEY, chat_id INTEGER NOT NULL, message_id INTEGER, subject TEXT NOT NULL, field TEXT NOT NULL,
        op TEXT NOT NULL DEFAULT 'add', value TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', created REAL NOT NULL
    );
    CREATE INDEX IF NOT EXISTS status_events_chat ON status_events (chat_id);
    CREATE TABLE IF NOT EXISTS world_events (
        id INTEGER PRIMARY KEY, chat_id INTEGER NOT NULL, message_id INTEGER, world_time TEXT NOT NULL, text TEXT NOT NULL,
        kind TEXT NOT NULL DEFAULT 'kejadian', known_to TEXT NOT NULL DEFAULT '[]', public INTEGER NOT NULL DEFAULT 0,
        shown INTEGER NOT NULL DEFAULT 0, created REAL NOT NULL
    );
    CREATE INDEX IF NOT EXISTS world_events_chat ON world_events (chat_id);
    CREATE TABLE IF NOT EXISTS dice_log (
        id INTEGER PRIMARY KEY, chat_id INTEGER NOT NULL, message_id INTEGER, event TEXT NOT NULL, odds REAL NOT NULL,
        roll REAL NOT NULL, success INTEGER NOT NULL, created REAL NOT NULL
    );
    CREATE TABLE IF NOT EXISTS memories (
        id INTEGER PRIMARY KEY, scope TEXT NOT NULL DEFAULT 'story', card_id INTEGER, story_id INTEGER, chat_id INTEGER,
        kind TEXT NOT NULL DEFAULT 'fact', text TEXT NOT NULL, created REAL NOT NULL, updated REAL NOT NULL
    );
    CREATE VIRTUAL TABLE IF NOT EXISTS memories_fts USING fts5(text, content='memories', content_rowid='id');
    CREATE TRIGGER IF NOT EXISTS memories_ai AFTER INSERT ON memories BEGIN
        INSERT INTO memories_fts(rowid, text) VALUES (new.id, new.text);
    END;
    CREATE TRIGGER IF NOT EXISTS memories_ad AFTER DELETE ON memories BEGIN
        INSERT INTO memories_fts(memories_fts, rowid, text) VALUES ('delete', old.id, old.text);
    END;
    CREATE TRIGGER IF NOT EXISTS memories_au AFTER UPDATE OF text ON memories BEGIN
        INSERT INTO memories_fts(memories_fts, rowid, text) VALUES ('delete', old.id, old.text);
        INSERT INTO memories_fts(rowid, text) VALUES (new.id, new.text);
    END;
    CREATE TABLE IF NOT EXISTS memory_log (
        id INTEGER PRIMARY KEY, memory_id INTEGER, action TEXT NOT NULL, before TEXT, after TEXT,
        chat_id INTEGER, created REAL NOT NULL, undone INTEGER NOT NULL DEFAULT 0
    );
    CREATE TABLE IF NOT EXISTS vectors (kind TEXT NOT NULL, ref_id INTEGER NOT NULL, dim INTEGER NOT NULL, v BLOB NOT NULL,
        PRIMARY KEY (kind, ref_id));
    CREATE TABLE IF NOT EXISTS side_log (
        id INTEGER PRIMARY KEY, kind TEXT NOT NULL, chat_id INTEGER, message_id INTEGER, data TEXT NOT NULL, created REAL NOT NULL
    );
    CREATE INDEX IF NOT EXISTS side_log_chat ON side_log (chat_id, kind);
    CREATE TABLE IF NOT EXISTS vocab (
        id INTEGER PRIMARY KEY, term TEXT NOT NULL, lang TEXT NOT NULL DEFAULT '', translation TEXT NOT NULL DEFAULT '',
        note TEXT NOT NULL DEFAULT '', example TEXT NOT NULL DEFAULT '', due REAL NOT NULL, interval REAL NOT NULL DEFAULT 0,
        ease REAL NOT NULL DEFAULT 2.5, reps INTEGER NOT NULL DEFAULT 0, created REAL NOT NULL
    );
    """

    SCHEMA_VERSION = 1


    class Store:
        """One SQLite file: chats (message trees), cards, lore, facts, world state, memories, vectors, vocabulary."""

        def __init__(self, path):
            self.file = Path(path)
            self.lock = threading.RLock()
            self.rev = 0
            self.listeners = []
            self._open()

        # ---------- connection ----------

        def _open(self):
            self.conn = sqlite3.connect(self.file, check_same_thread=False)
            self.conn.row_factory = sqlite3.Row
            self.conn.execute("PRAGMA journal_mode=WAL")
            self.conn.execute("PRAGMA foreign_keys=OFF")
            self._migrate()

        def _columns(self, table):
            return {r[1] for r in self.conn.execute(f"PRAGMA table_info({table})")}

        def _migrate(self):
            version = self.conn.execute("PRAGMA user_version").fetchone()[0]
            if version > SCHEMA_VERSION:
                raise ValueError(f"Database dibuat versi notebook yang lebih baru (skema {version}).")
            if "messages" in self._tables() and "seq" in self._columns("messages"):
                self._migrate_legacy()
            # Every statement is IF NOT EXISTS, so this also adds tables introduced after a database was created.
            self.conn.executescript(_SCHEMA_V1)
            self.conn.execute(f"PRAGMA user_version = {SCHEMA_VERSION}")
            self.conn.commit()

        def _tables(self):
            return {r[0] for r in self.conn.execute("SELECT name FROM sqlite_master WHERE type IN ('table', 'view')")}

        def _migrate_legacy(self):
            """Database from the old notebook (linear messages with seq) -> message trees."""
            c = self.conn
            old = self._tables()
            for t in ("messages_fts", "memories_fts"):
                if t in old:
                    c.execute(f"DROP TABLE {t}")
            for trg in ("messages_ai", "messages_ad", "memories_ai", "memories_ad"):
                c.execute(f"DROP TRIGGER IF EXISTS {trg}")
            for t in ("chats", "messages", "summaries", "memories"):
                if t in old:
                    c.execute(f"ALTER TABLE {t} RENAME TO legacy_{t}")
            c.executescript(_SCHEMA_V1)
            seq_to_id = {}
            if "chats" in old:
                for ch in c.execute("SELECT * FROM legacy_chats ORDER BY id").fetchall():
                    c.execute("INSERT INTO chats (id, title, system, kind, settings, created, updated) VALUES (?, ?, ?, 'chat', '{}', ?, ?)",
                              (ch["id"], ch["title"], ch["system"] or "", ch["created"], ch["updated"]))
            prev = {}
            for m in c.execute("SELECT * FROM legacy_messages ORDER BY chat_id, seq").fetchall():
                parent = prev.get(m["chat_id"])
                c.execute("INSERT INTO messages (id, chat_id, parent_id, role, content, reasoning, tool_calls, tool_call_id, meta, created) "
                          "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                          (m["id"], m["chat_id"], parent, m["role"], m["content"] or "", m["reasoning"] or "",
                           m["tool_calls"], m["tool_call_id"], m["meta"] or "{}", m["created"]))
                prev[m["chat_id"]] = m["id"]
                seq_to_id[(m["chat_id"], m["seq"])] = m["id"]
            for chat_id, head in prev.items():
                c.execute("UPDATE chats SET head_id = ? WHERE id = ?", (head, chat_id))
            if "chats" in old and "strip_upto" in {r[1] for r in c.execute("PRAGMA table_info(legacy_chats)")}:
                for ch in c.execute("SELECT id, strip_upto FROM legacy_chats").fetchall():
                    node = seq_to_id.get((ch["id"], ch["strip_upto"]), 0)
                    c.execute("UPDATE chats SET strip_node = ? WHERE id = ?", (node, ch["id"]))
            if "summaries" in old:
                for s in c.execute("SELECT * FROM legacy_summaries").fetchall():
                    node = seq_to_id.get((s["chat_id"], s["upto_seq"]))
                    if node:
                        c.execute("INSERT INTO summaries (chat_id, node_id, level, text, created) VALUES (?, ?, 'chunk', ?, ?)",
                                  (s["chat_id"], node, s["text"], s["created"]))
            if "memories" in old:
                for m in c.execute("SELECT * FROM legacy_memories").fetchall():
                    kind = "summary_core" if (m["text"] or "").startswith("[Ringkasan chat") else "fact"
                    c.execute("INSERT INTO memories (scope, kind, text, created, updated) VALUES ('user', ?, ?, ?, ?)",
                              (kind, m["text"], m["created"], m["created"]))
            for t in ("chats", "messages", "summaries", "memories"):
                if t in old:
                    c.execute(f"DROP TABLE legacy_{t}")
            c.execute("DROP TABLE IF EXISTS chat_memory_snapshot")
            c.commit()

        # ---------- primitives ----------

        def q(self, sql, args=()):
            with self.lock:
                return [dict(r) for r in self.conn.execute(sql, args).fetchall()]

        def one(self, sql, args=()):
            with self.lock:
                r = self.conn.execute(sql, args).fetchone()
                return dict(r) if r else None

        def x(self, sql, args=()):
            with self.lock:
                cur = self.conn.execute(sql, args)
                self.conn.commit()
                self._changed()
                return cur.lastrowid

        def many(self, sql, rows):
            with self.lock:
                self.conn.executemany(sql, rows)
                self.conn.commit()
                self._changed()

        def _changed(self):
            self.rev += 1
            for fn in list(self.listeners):
                try:
                    fn(self.rev)
                except Exception:
                    pass

        def meta_get(self, key, default=None):
            r = self.one("SELECT value FROM meta WHERE key = ?", (key,))
            return json.loads(r["value"]) if r else default

        def meta_set(self, key, value):
            if self.meta_get(key) == value:
                return  # unchanged: do not mark the database dirty (that would trigger a backup)
            self.x("INSERT INTO meta (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
                   (key, json.dumps(value)))

        def side_log(self, kind, data, chat_id=None, message_id=None):
            """Keep the output of side tasks (drafts, explanations, transcripts, server logs) so nothing is lost."""
            text = json.dumps(data, ensure_ascii=False, default=str)[:400_000]
            return self.x("INSERT INTO side_log (kind, chat_id, message_id, data, created) VALUES (?, ?, ?, ?, ?)",
                          (kind, chat_id, message_id, text, time.time()))

        def side_logs(self, chat_id=None, kind=None, limit=50):
            sql, args = "SELECT * FROM side_log WHERE 1 = 1", []
            if chat_id:
                sql += " AND chat_id = ?"
                args.append(chat_id)
            if kind:
                sql += " AND kind = ?"
                args.append(kind)
            rows = self.q(sql + " ORDER BY id DESC LIMIT ?", args + [limit])
            for r in rows:
                r["data"] = json.loads(r["data"])
            return rows

        # ---------- export / import ----------

        def export_bytes(self):
            with self.lock:
                self.conn.commit()
                return self.conn.serialize()

        def backup_to(self, path):
            """Consistent copy of the live database (SQLite backup API)."""
            with self.lock:
                dst = sqlite3.connect(path)
                try:
                    self.conn.backup(dst)
                finally:
                    dst.close()

        def import_bytes(self, data):
            """Replace the database with an uploaded one (old or new format) after checking it is ours."""
            probe = sqlite3.connect(":memory:")
            probe.deserialize(data)
            names = {r[0] for r in probe.execute("SELECT name FROM sqlite_master WHERE type = 'table'")}
            probe.close()
            if not {"chats", "messages"} <= names:
                raise ValueError("File bukan database Qwen Chat.")
            with self.lock:
                self.conn.close()
                for suffix in ("-wal", "-shm"):
                    Path(str(self.file) + suffix).unlink(missing_ok=True)
                self.file.write_bytes(data)
                self._open()
                self._changed()

        # ---------- chats ----------

        def new_chat(self, title, kind="chat", story_id=None, settings=None, system=""):
            now = time.time()
            return self.x("INSERT INTO chats (title, kind, story_id, settings, system, created, updated) VALUES (?, ?, ?, ?, ?, ?, ?)",
                          (title, kind, story_id, json.dumps(settings or {}), system, now, now))

        def chat(self, chat_id):
            c = self.one("SELECT * FROM chats WHERE id = ?", (chat_id,))
            if c:
                c["settings"] = json.loads(c["settings"] or "{}")
            return c

        def chat_settings(self, chat_id, **updates):
            c = self.chat(chat_id)
            s = {**(c["settings"] if c else {}), **updates}
            self.x("UPDATE chats SET settings = ?, updated = ? WHERE id = ?", (json.dumps(s), time.time(), chat_id))
            return s

        def chats(self):
            return self.q("SELECT id, title, kind, story_id, updated FROM chats ORDER BY updated DESC")

        def delete_chat(self, chat_id):
            with self.lock:
                ids = [r["id"] for r in self.q("SELECT id FROM messages WHERE chat_id = ?", (chat_id,))]
                for i in range(0, len(ids), 500):
                    part = ids[i:i + 500]
                    marks = ",".join("?" * len(part))
                    self.conn.execute(f"DELETE FROM attachments WHERE message_id IN ({marks})", part)
                    self.conn.execute(f"DELETE FROM vectors WHERE kind = 'msg' AND ref_id IN ({marks})", part)
                for table in ("messages", "summaries", "snapshots", "chapters", "status_events", "world_events",
                              "dice_log", "pending_changes", "memory_log", "side_log"):
                    self.conn.execute(f"DELETE FROM {table} WHERE chat_id = ?", (chat_id,))
                self.conn.execute("DELETE FROM memories WHERE chat_id = ? AND (scope = 'chat' OR kind = 'summary_core')", (chat_id,))
                self.conn.execute("DELETE FROM chats WHERE id = ?", (chat_id,))
                self.conn.commit()
                self._changed()

        # ---------- message trees ----------

        def add_message(self, chat_id, parent_id, role, content="", reasoning="", tool_calls=None, tool_call_id=None,
                        meta=None, ooc=False, status="final", media=None, set_head=True):
            with self.lock:
                cur = self.conn.execute(
                    "INSERT INTO messages (chat_id, parent_id, role, content, reasoning, tool_calls, tool_call_id, ooc, status, meta, created) "
                    "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (chat_id, parent_id, role, content or "", reasoning or "",
                     json.dumps(tool_calls) if tool_calls else None, tool_call_id, int(bool(ooc)), status,
                     json.dumps(meta or {}), time.time()))
                mid = cur.lastrowid
                for a in media or []:
                    self.conn.execute("INSERT INTO attachments (message_id, kind, mime, name, data) VALUES (?, ?, ?, ?, ?)",
                                      (mid, a["kind"], a["mime"], a["name"], a["data"]))
                if set_head:
                    self.conn.execute("UPDATE chats SET head_id = ?, updated = ? WHERE id = ?", (mid, time.time(), chat_id))
                self.conn.commit()
                self._changed()
                return mid

        def update_message(self, mid, **fields):
            if "meta" in fields and isinstance(fields["meta"], dict):
                fields["meta"] = json.dumps(fields["meta"])
            if "tool_calls" in fields and isinstance(fields["tool_calls"], list):
                fields["tool_calls"] = json.dumps(fields["tool_calls"])
            sets = ", ".join(f"{k} = ?" for k in fields)
            self.x(f"UPDATE messages SET {sets} WHERE id = ?", (*fields.values(), mid))

        def msg(self, mid):
            m = self.one("SELECT * FROM messages WHERE id = ?", (mid,))
            if m:
                m["meta"] = json.loads(m["meta"] or "{}")
            return m

        def set_head(self, chat_id, mid):
            self.x("UPDATE chats SET head_id = ?, updated = ? WHERE id = ?", (mid, time.time(), chat_id))

        def _parents(self, chat_id):
            return {r["id"]: r["parent_id"] for r in self.q("SELECT id, parent_id FROM messages WHERE chat_id = ?", (chat_id,))}

        def path_ids(self, chat_id, head=None):
            """Message ids from the root to `head` (default: the chat's head)."""
            if head is None:
                c = self.one("SELECT head_id FROM chats WHERE id = ?", (chat_id,))
                head = c["head_id"] if c else None
            parents = self._parents(chat_id)
            out, cur, seen = [], head, set()
            while cur and cur in parents and cur not in seen:
                seen.add(cur)
                out.append(cur)
                cur = parents[cur]
            return out[::-1]

        def path(self, chat_id, head=None, ids=None):
            """Full message rows along the active path, in order, with meta decoded."""
            ids = ids if ids is not None else self.path_ids(chat_id, head)
            rows = {}
            for i in range(0, len(ids), 500):
                part = ids[i:i + 500]
                for r in self.q(f"SELECT * FROM messages WHERE id IN ({','.join('?' * len(part))})", part):
                    r["meta"] = json.loads(r["meta"] or "{}")
                    rows[r["id"]] = r
            return [rows[i] for i in ids if i in rows]

        def children(self, chat_id, parent_id):
            if parent_id is None:
                return [r["id"] for r in self.q("SELECT id FROM messages WHERE chat_id = ? AND parent_id IS NULL ORDER BY id", (chat_id,))]
            return [r["id"] for r in self.q("SELECT id FROM messages WHERE chat_id = ? AND parent_id = ? ORDER BY id",
                                            (chat_id, parent_id))]

        def deepest(self, chat_id, mid):
            """Follow the newest child down to a leaf (used when switching to another branch)."""
            kids = {}
            for r in self.q("SELECT id, parent_id FROM messages WHERE chat_id = ? ORDER BY id", (chat_id,)):
                kids.setdefault(r["parent_id"], []).append(r["id"])
            cur = mid
            while kids.get(cur):
                cur = kids[cur][-1]
            return cur

        def attachments(self, ids):
            out = {}
            for i in range(0, len(ids), 500):
                part = ids[i:i + 500]
                for a in self.q(f"SELECT id, message_id, kind, mime, name, data FROM attachments WHERE message_id IN "
                                f"({','.join('?' * len(part))}) ORDER BY id", part):
                    out.setdefault(a["message_id"], []).append(a)
            return out


    STORE = Store(CFG.DB_PATH)
    return (STORE,)


@app.cell(hide_code=True)
def _(CFG, Path, STORE, os, threading, time):
    class Backup:
        """Copy the SQLite file to a private Hugging Face dataset repo when it has changed.
        The token is kept only in this object (kernel memory): never written to the database, disk or the backup."""

        KEEP = 20

        def __init__(self, store):
            self.store = store
            self.token = ""
            self.repo = ""
            self.interval = 600
            self.saved_rev = store.rev
            self.status = {"enabled": False, "last_ok": None, "last_error": "", "repo": "", "busy": False}
            self.lock = threading.Lock()
            self.thread = None

        def configure(self, token, repo, interval):
            self.token = (token or os.environ.get("HF_TOKEN", "")).strip()
            self.interval = max(60, int(interval))
            self.repo = repo.strip()
            self.status["enabled"] = bool(self.token)
            if self.token and not self.repo:
                try:
                    self.repo = f"{self._api().whoami()['name']}/qwen-chat-backup"
                except Exception as e:
                    self.status["last_error"] = f"Token tidak bisa dipakai: {type(e).__name__}"
                    self.status["enabled"] = False
            self.status["repo"] = self.repo
            if self.status["enabled"]:
                self.store.meta_set("backup", {"repo": self.repo, "interval": self.interval})
            if self.status["enabled"] and (self.thread is None or not self.thread.is_alive()):
                self.thread = threading.Thread(target=self._loop, daemon=True)
                self.thread.start()

        def _api(self):
            from huggingface_hub import HfApi
            return HfApi(token=self.token)

        def _loop(self):
            while self.status["enabled"]:
                time.sleep(self.interval)
                if self.store.rev != self.saved_rev:
                    self.backup_now()

        def backup_now(self):
            if not self.token:
                raise RuntimeError("Isi token HF dulu.")
            with self.lock:
                self.status["busy"] = True
                rev = self.store.rev
                tmp = CFG.WORK / "backup-upload.sqlite"
                try:
                    self.store.backup_to(tmp)
                    api = self._api()
                    api.create_repo(self.repo, repo_type="dataset", private=True, exist_ok=True)
                    stamp = time.strftime("%Y%m%d-%H%M%S")
                    from huggingface_hub import CommitOperationAdd, CommitOperationDelete
                    ops = [CommitOperationAdd(f"backups/qwen-chat-{stamp}.sqlite", str(tmp)),
                           CommitOperationAdd("latest.sqlite", str(tmp))]
                    old = sorted(f for f in api.list_repo_files(self.repo, repo_type="dataset") if f.startswith("backups/"))
                    ops += [CommitOperationDelete(f) for f in old[:max(0, len(old) + 1 - self.KEEP)]]
                    api.create_commit(self.repo, ops, commit_message=f"backup {stamp}", repo_type="dataset")
                    self.saved_rev = rev
                    self.status.update(last_ok=time.time(), last_error="")
                except Exception as e:
                    self.status["last_error"] = f"{type(e).__name__}: {str(e)[:200]}"
                    raise
                finally:
                    self.status["busy"] = False
                    tmp.unlink(missing_ok=True)

        def restore_latest(self):
            from huggingface_hub import hf_hub_download
            path = hf_hub_download(self.repo, "latest.sqlite", repo_type="dataset", token=self.token,
                                   local_dir=str(CFG.WORK / "restore"), force_download=True)
            self.store.import_bytes(Path(path).read_bytes())
            self.saved_rev = self.store.rev

        def dirty(self):
            return self.store.rev != self.saved_rev


    BACKUP = Backup(STORE)
    return (BACKUP,)


@app.cell(hide_code=True)
def _(STORE, mo):
    bk_token = mo.ui.text(kind="password", label="Token Hugging Face (write, sebaiknya fine-grained ke repo backup saja)",
                          full_width=True)
    _bk_last = STORE.meta_get("backup", {}) or {}
    _bk_choices = {"5 menit": 300, "10 menit": 600, "30 menit": 1800}
    bk_repo = mo.ui.text(value=_bk_last.get("repo", ""), label="Repo dataset private (kosong = <username>/qwen-chat-backup)",
                         full_width=True)
    bk_interval = mo.ui.dropdown(options=_bk_choices, label="Backup otomatis tiap",
                                 value=next((k for k, v in _bk_choices.items() if v == _bk_last.get("interval")), "10 menit"))
    bk_now = mo.ui.run_button(label="Backup sekarang")
    bk_restore = mo.ui.run_button(label="Pulihkan terbaru", kind="danger")
    mo.accordion({"Backup ke Hugging Face": mo.vstack([
        mo.md("Token hanya disimpan di memori kernel, tidak pernah ditulis ke database, disk, atau file backup. "
              "Kalau kosong, dipakai env `HF_TOKEN`. Repo dibuat **private**."),
        bk_token, mo.hstack([bk_repo, bk_interval], widths=[3, 1]), mo.hstack([bk_now, bk_restore], justify="start"),
    ])})
    return bk_interval, bk_now, bk_repo, bk_restore, bk_token


@app.cell(hide_code=True)
def _(BACKUP, bk_interval, bk_now, bk_repo, bk_restore, bk_token, mo):
    def _backup_act():
        BACKUP.configure(bk_token.value, bk_repo.value, bk_interval.value)
        if not BACKUP.status["enabled"]:
            return mo.md(f"_Backup mati: {BACKUP.status['last_error'] or 'belum ada token.'}_")
        try:
            if bk_now.value:
                BACKUP.backup_now()
                return mo.callout(mo.md(f"Backup tersimpan di `{BACKUP.repo}`."), kind="success")
            if bk_restore.value:
                BACKUP.restore_latest()
                return mo.callout(mo.md(f"Database dipulihkan dari `{BACKUP.repo}/latest.sqlite`. Muat ulang jendela chat "
                                        f"(pilih chat lagi dari sidebar)."), kind="success")
        except Exception as e:
            return mo.callout(mo.md(f"Gagal: {e}"), kind="danger")
        return mo.md(f"_Backup otomatis aktif ke `{BACKUP.repo}` setiap {BACKUP.interval // 60} menit kalau ada perubahan._")


    _backup_act()


@app.cell(hide_code=True)
def _(re):
    class TXT:
        """Text utilities: search queries, counting, similarity, and the RP quality checks."""

        STOP = {
            "id": set("""yang dan di ke dari ini itu dengan untuk pada adalah dalam tidak akan juga sudah saya aku kamu dia
                mereka kami kita ada atau bisa jadi karena oleh seperti tapi tetapi lalu kemudian saat ketika masih hanya
                lebih sangat apa siapa bagaimana mengapa kenapa mana sini sana begitu begini pun lagi telah belum harus
                sebuah seorang para nya ya tak tidak bukan agar supaya setelah sebelum sambil sementara hingga sampai
                antara tentang terhadap bagi tanpa namun maka jika kalau kan dong sih deh nah oh wah mu ku""".split()),
            "de": set("""der die das den dem des ein eine einer einem einen eines und oder aber ist sind war waren bin bist
                sein hat haben hatte ich du er sie es wir ihr mich dich sich mir dir ihm ihn uns euch nicht kein keine
                auch noch schon nur so wie was wer wo wann warum mit von zu im in am an auf aus bei nach für über unter
                vor dass ob wenn als um ja nein doch mal dann denn hier da""".split()),
            "en": set("""the a an and or but is are was were be been being have has had do does did i you he she it we they
                me him her us them my your his its our their this that these those of to in on at by for with from as
                not no so if then than there here what who when where why how all any can could would should will
                just very into over under about""".split()),
        }
        ALL_STOP = set().union(*STOP.values())
        ABBREV = {"z.b.", "d.h.", "u.a.", "usw.", "bzw.", "dr.", "hr.", "fr.", "mr.", "mrs.", "st.", "dll.", "dsb.",
                  "dkk.", "no.", "nr.", "vs.", "etc.", "ca.", "sog.", "prof.", "sgt.", "lt.", "kpt.", "jl."}

        @staticmethod
        def words(text):
            return re.findall(r"\w+", (text or "").lower())

        @staticmethod
        def content_words(text):
            return [w for w in TXT.words(text) if w not in TXT.ALL_STOP and len(w) > 1 and not w.isdigit()]

        @staticmethod
        def fts_query(text, limit=20):
            """FTS5 OR-query of quoted content words, so punctuation never breaks MATCH. '' when nothing is left."""
            seen, out = set(), []
            for w in TXT.content_words(text):
                if w not in seen:
                    seen.add(w)
                    out.append(f'"{w}"')
                if len(out) >= limit:
                    break
            return " OR ".join(out)

        @staticmethod
        def overlap(text, other):
            """How many distinct content words two texts share."""
            return len(set(TXT.content_words(text)) & set(TXT.content_words(other)))

        @staticmethod
        def jaccard(a, b):
            sa, sb = set(TXT.content_words(a)), set(TXT.content_words(b))
            return len(sa & sb) / len(sa | sb) if sa and sb else 0.0

        # ---------- counting ----------

        @staticmethod
        def paragraphs(text):
            t = (text or "").strip()
            if not t:
                return []
            blocks = [b.strip() for b in re.split(r"\n\s*\n", t) if b.strip()]
            if len(blocks) == 1 and "\n" in t:
                blocks = [b.strip() for b in t.split("\n") if b.strip()]
            return blocks

        @staticmethod
        def sentences(text):
            """Split into sentences. Quotes stay with their sentence; abbreviations and decimals do not split."""
            t = re.sub(r"\s+", " ", (text or "").strip())
            if not t:
                return []
            out, start = [], 0
            # A translation in parentheses right after a quote belongs to the same sentence, so "(" never opens one.
            for m in re.finditer(r"[.!?…]+[\"'”’»)]*(?=\s+[\"'“„«]?[A-ZÄÖÜ0-9]|\s*$)", t):
                end = m.end()
                piece = t[start:end].strip()
                last = piece.split(" ")[-1].lower()
                if last in TXT.ABBREV or re.search(r"\d\.\d*$", piece):
                    continue
                if piece:
                    out.append(piece)
                start = end
            rest = t[start:].strip()
            if rest:
                out.append(rest)
            return out

        @staticmethod
        def shape(text):
            """(paragraph count, sentences per paragraph) of a reply."""
            paras = TXT.paragraphs(text)
            return len(paras), [len(TXT.sentences(p)) for p in paras]

        # ---------- RP checks ----------

        @staticmethod
        def repeated_phrases(text, previous, n=5, min_hits=2, top=5):
            """Word n-grams of `text` that already appeared in the previous replies (min_hits times in total)."""
            def grams(s):
                w = TXT.words(s)
                return [" ".join(w[i:i + n]) for i in range(len(w) - n + 1)]
            counts = {}
            for p in previous:
                for g in set(grams(p)):
                    counts[g] = counts.get(g, 0) + 1
            hits = []
            for g in dict.fromkeys(grams(text)):
                if counts.get(g, 0) + 1 >= min_hits and len(set(g.split()) - TXT.ALL_STOP) >= 2:
                    hits.append(g)
            # keep the longest distinct phrases: drop grams contained in an already kept one
            kept = []
            for g in hits:
                if not any(g in k for k in kept):
                    kept.append(g)
            return kept[:top]

        @staticmethod
        def banned_hits(text, phrases):
            low = (text or "").lower()
            return [p for p in phrases if p and p.lower() in low]

        @staticmethod
        def dedupe_parens(text):
            """Drop a parenthetical that repeats the one right before it, e.g. "(Iya.) (Iya)" -> "(Iya.)"."""
            parts = re.split(r"(\([^()\n]{1,300}\))", text or "")
            out, last = [], None
            for p in parts:
                if p.startswith("(") and p.endswith(")"):
                    norm = re.sub(r"[\s.!?,…]+", " ", p[1:-1]).strip().lower()
                    if norm == last:
                        while out and not out[-1].strip():
                            out.pop()
                        continue
                    last = norm
                elif p.strip():
                    last = None
                out.append(p)
            return "".join(out)

        @staticmethod
        def narration_language(text, expected):
            """Share of stopwords per language outside quotes. Returns (dominant language, shares)."""
            outside = re.sub(r"[\"“„«][^\"”“»]*[\"”»]", " ", text or "")
            outside = re.sub(r"\([^()]*\)", " ", outside)
            w = TXT.words(outside)
            shares = {lang: sum(1 for x in w if x in stop) for lang, stop in TXT.STOP.items()}
            total = sum(shares.values()) or 1
            shares = {k: v / total for k, v in shares.items()}
            dominant = max(shares, key=shares.get) if w else expected
            return dominant, shares

        @staticmethod
        def split_dialogue(text):
            """Count quote fragments followed by a short translation: the "Das..." (Itu) "...ist..." pattern.
            A fragment has an ellipsis or at most two words; a whole short sentence does not count."""
            n = 0
            for m in re.finditer(r"[\"“„]([^\"”“]{0,40})[\"”]\s*\(([^()]{1,30})\)", text or ""):
                inner = m.group(1).strip()
                if "..." in inner or "…" in inner or len(inner.split()) <= 2:
                    n += 1
            return n

        ACTS_FOR_USER = re.compile(
            r"\b(kamu|Kamu|anda|Anda)\s+(berkata|bilang|menjawab|bertanya|berteriak|berbisik|mengatakan|memutuskan|"
            r"setuju|tersenyum dan berkata)\b|\b(katamu|ucapmu|jawabmu|tanyamu|bisikmu|teriakmu)\b|"
            r"\byou (say|said|reply|replied|ask|asked|decide|decided)\b", re.I)

        @staticmethod
        def acts_for_user(text, persona_name=""):
            hits = [m.group(0) for m in TXT.ACTS_FOR_USER.finditer(text or "")]
            if persona_name:
                hits += re.findall(rf"\b{re.escape(persona_name)}\s+(?:berkata|menjawab|bertanya|says|said)\b", text or "")
            return hits

        # ---------- user input ----------

        SLASH = ("ooc", "note", "reroll", "continue", "bab", "ingat", "impersonate", "studio", "cek")

        @staticmethod
        def parse_input(text):
            """-> {"kind": "slash"|"ooc"|"text", "cmd", "arg", "text"}"""
            t = (text or "").strip()
            m = re.match(r"^/(\w+)\s*(.*)$", t, re.S)
            if m and m.group(1).lower() in TXT.SLASH:
                cmd = m.group(1).lower()
                if cmd == "ooc":
                    return {"kind": "ooc", "text": m.group(2).strip()}
                return {"kind": "slash", "cmd": cmd, "arg": m.group(2).strip()}
            if t.startswith("((") and t.endswith("))"):
                return {"kind": "ooc", "text": t[2:-2].strip()}
            return {"kind": "text", "text": t}

    return (TXT,)


